import type { VendorCategory } from "@birdsi/shared";

/**
 * Vendors birdsI recognises on sight. Detection runs on package names, env
 * var names, URL domains and config files. Anything not here is still found
 * through its env var name and described from the web.
 */
export interface CatalogEntry {
  slug: string;
  name: string;
  category: VendorCategory;
  what: string;
  packages: RegExp[];
  envVars: RegExp[];
  domains: string[];
  configFiles: RegExp[];
  pricingUrl: string | null;
  docsUrl: string | null;
  /** Where the owner finds plan and usage by hand, for questions. */
  dashboardUrl: string | null;
  /** The connector slug when birdsI can read the account. */
  connector: string | null;
  /** Pay-as-you-go services have no plan to ask about; their tiers are add-ons or consumer products. */
  planless: boolean;
}

const e = (slug: string, name: string, category: VendorCategory, what: string, rest: Partial<Omit<CatalogEntry, "slug" | "name" | "category" | "what">>): CatalogEntry => ({
  slug,
  name,
  category,
  what,
  packages: rest.packages ?? [],
  envVars: rest.envVars ?? [],
  domains: rest.domains ?? [],
  configFiles: rest.configFiles ?? [],
  pricingUrl: rest.pricingUrl ?? null,
  docsUrl: rest.docsUrl ?? null,
  dashboardUrl: rest.dashboardUrl ?? null,
  connector: rest.connector ?? null,
  planless: rest.planless ?? false,
});

